INSERT INTO `room_categories` VALUES (2, 0, 2500000.00, 2, 500000.00, 250000.00, 1, 1, 1, 1, 3, 1, 65, 1, '1 Giường King 2m', 'Hướng vườn cảnh quan tươi mát', 'https://i.pinimg.com/1200x/32/4d/93/324d935a2dcf3e17755d9b2a56db8dd8.jpg,https://i.pinimg.com/1200x/92/da/a5/92daa5b7f54fb083037e380c346ec915.jpg,https://i.pinimg.com/736x/de/bf/21/debf21e88839c41b74110c968cb06580.jpg', 'Nipa Pool Villa', '2 chai nước suối, Trái cây tươi, Vang đỏ', 'Phòng nghỉ sang trọng với nội thất gỗ cao cấp, không gian ấm cúng đậm chất Á Đông, mang đến cảm giác thư thái và riêng tư tuyệt đối.');
INSERT INTO `room_categories` VALUES (2, 0, 3500000.00, 3, 600000.00, 300000.00, 1, 1, 1, 1, 3, 2, 80, 2, '1 Giường King 2m2', 'Hướng sông Thu Bồn thơ mộng', 'https://i.pinimg.com/1200x/e3/2a/bd/e32abd795403ecdc1f9a39cca7a2b36e.jpg,https://i.pinimg.com/1200x/fc/ad/21/fcad21b76553df856751ec8b465c4de1.jpg,https://i.pinimg.com/736x/95/83/75/95837513ef477c7674a49c40b64b7944.jpg', 'River Pool Villa', '4 chai nước suối, Trái cây, Trà chiều', 'Tuyệt tác nghỉ dưỡng nép mình bên dòng Thu Bồn thơ mộng, quyện hòa kiến trúc mộc mạc đậm hồn Việt cùng tiện nghi xa hoa, tạo nên chốn ẩn mình thư thái hoàn hảo.');
INSERT INTO `room_categories` VALUES (2, 0, 8000000.00, 4, 1000000.00, 500000.00, 1, 1, 1, 1, 4, 2, 120, 3, '2 Giường King', 'Hướng vườn thiền thanh tịnh', 'https://i.pinimg.com/736x/b5/99/a1/b599a169fc0d46ed80abf3658a5696ae.jpg,https://i.pinimg.com/736x/c8/95/86/c89586f5c7f42012ff96b71679b0f77e.jpg,https://i.pinimg.com/1200x/b8/56/8c/b8568cc6bbd6bdc0682a49645a902aba.jpg', 'Wellness Retreats', 'Nước detox, Trái cây Organic, Trà thảo mộc', 'Không gian chữa lành mang đậm hơi thở Á Đông truyền thống, bao bọc bởi thiên nhiên tĩnh mặc, nơi đánh thức mọi giác quan và tái tạo năng lượng tuyệt đối.');
INSERT INTO `room_categories` VALUES (2, 0, 2000000.00, 2, 400000.00, 200000.00, 1, 0, 1, 1, 3, 1, 45, 4, '1 Giường Queen 1m8', 'Hướng vườn nhiệt đới an yên', 'https://i.pinimg.com/1200x/4c/b3/5d/4cb35d45c3df7d2826dde080f3d5ee89.jpg,https://i.pinimg.com/736x/79/ae/eb/79aeeb12ae2779b5c3d6ddc4b282a7bf.jpg,https://i.pinimg.com/736x/a4/c6/4a/a4c64a255575700ce97e496092da44e5.jpg', 'Superior Room', '2 chai nước suối, Trà & Cà phê', 'Phòng nghỉ tinh tế hòa quyện vẻ đẹp Á Đông mộc mạc và sự thanh lịch hiện đại, mở ra không gian vườn nhiệt đới xanh mát rợp bóng cây.');
INSERT INTO `room_categories` VALUES (4, 0, 15000000.00, 6, 2000000.00, 1000000.00, 1, 1, 1, 1, 6, 3, 250, 5, '3 Giường King 2m2', 'Hướng panorama toàn cảnh Resort', 'https://i.pinimg.com/736x/4d/fb/df/4dfbdfe5caad42a0c83a885a21e544e5.jpg,https://i.pinimg.com/736x/03/18/7c/03187ce97e28a8e9fe9969c609f855d4.jpg,https://i.pinimg.com/1200x/50/a8/36/50a836ae68f0b08ae84c37739acbd6c8.jpg', 'Presidential Suite', 'Minibar miễn phí, Rượu Champagne, Bánh ngọt', 'Không gian vương giả đẳng cấp bậc nhất, nơi nghệ thuật kiến trúc tinh hoa hội tụ cùng tầm nhìn ôm trọn cảnh sắc thiên nhiên hùng vĩ của resort, định nghĩa lại trải nghiệm nghỉ dưỡng xa xỉ.');
INSERT INTO `room_categories` VALUES (2, 0, 3000000.00, 2, 600000.00, 300000.00, 1, 1, 1, 1, 3, 1, 50, 6, '1 Giường King 2m2', 'Hướng không gian mở an yên', 'https://i.pinimg.com/736x/19/dc/7a/19dc7a8862941a3c505cf083e9b5e4d0.jpg,https://i.pinimg.com/736x/c0/7e/80/c07e80ff7753364ef1cc210a29189b79.jpg,https://i.pinimg.com/736x/f5/31/4f/f5314f4fcb55d67b986d5acf0d2e080f.jpg', 'Heritage Wood Bungalow', '2 chai nước suối, Trái cây tươi', 'Lấy cảm hứng từ nếp nhà truyền thống Á Đông, Bungalow sử dụng chất liệu gỗ tự nhiên nguyên bản, mang đến cảm giác thân thuộc, ấm cúng và an yên đến lạ.');
INSERT INTO `room_categories` VALUES (2, 2, 9500000.00, 5, 500000.00, 250000.00, 1, 0, 1, 1, 4, 4, 90, 7, '1 Giường King & 2 Giường Đơn', 'Hướng vườn êm đềm', 'https://i.pinimg.com/736x/22/18/4d/22184d22b4ea5819d81c01a448154d7b.jpg,https://i.pinimg.com/736x/fe/13/9b/fe139b0daaf5570ab624e4e74c4ef297.jpg,https://i.pinimg.com/736x/2f/46/6d/2f466d84d125ebd5589d049782c2c34a.jpg', 'Family Connecting Room', '4 chai nước suối, Bánh quy, Trà, Sách', 'Không gian ấm cúng thiết kế mở kết nối yêu thương, nơi cả gia đình quây quần lưu giữ những khoảnh khắc trọn vẹn hạnh phúc giữa thiên nhiên bình yên.');
INSERT INTO `room_categories` VALUES (2, 0, 1800000.00, 2, 350000.00, 150000.00, 0, 0, 1, 1, 2, 1, 40, 8, '1 Giường 1m8', 'Hướng không gian tĩnh lặng', 'https://i.pinimg.com/1200x/25/df/c6/25dfc64dd98b33514f5f5597b6258f6a.jpg,https://i.pinimg.com/736x/5c/e6/b2/5ce6b284f68e75c930d84214882c1451.jpg,https://i.pinimg.com/1200x/79/71/37/797137545c45e65d4e46dbc8090926fe.jpg', 'Classic Room', '2 chai nước suối, Trà', 'Không gian nghỉ dưỡng tối giản nhưng tinh tế, mang lại cảm giác thoải mái và thư thái với tiện nghi cơ bản, là lựa chọn hoàn hảo cho những ai yêu thích sự mộc mạc.');
INSERT INTO `room_categories` VALUES (2, 0, 12000000.00, 4, 1500000.00, 750000.00, 1, 1, 1, 1, 4, 2, 180, 9, '2 Giường King siêu lớn', 'Hướng toàn cảnh khu nghỉ dưỡng', 'https://i.pinimg.com/1200x/3d/2d/36/3d2d36b8ccf42d575802b00708304eaf.jpg,https://i.pinimg.com/1200x/63/a2/59/63a259ff25028ebc7ee6738f99f8f2e0.jpg,https://i.pinimg.com/1200x/31/21/fe/3121fe2b26a4e17b9417f3f032c9e66b.jpg', 'Heritage Suite', 'Rượu vang cao cấp, Trái cây nhập khẩu, Minibar', 'Tuyệt tác không gian mang đậm dấu ấn di sản, tôn vinh nghệ thuật kiến trúc Á Đông kết hợp hoàn hảo cùng tiện nghi xa xỉ bậc nhất, đem lại trải nghiệm nghỉ dưỡng thượng lưu độc bản.');
INSERT INTO `room_categories` VALUES (2, 0, 1500000.00, 2, 300000.00, 150000.00, 0, 0, 0, 1, 2, 1, 35, 10, '1 Giường Queen 1m8', 'Hướng khu phố yên bình', 'https://i.pinimg.com/1200x/5a/93/2a/5a932a215282cb5cbcd7c6c6bcbe0302.jpg,https://i.pinimg.com/736x/02/f7/c6/02f7c655b9c1afc45b77f2a6701a9e9b.jpg,https://i.pinimg.com/1200x/fe/52/09/fe5209e25f3a6bcc67e952e9321fc815.jpg', 'Cozy Studio Room', '2 chai nước suối, Cà phê hòa tan', 'Không gian nhỏ gọn và ấm áp với thiết kế thông minh, trang bị đầy đủ tiện nghi thiết yếu, là điểm dừng chân lý tưởng để bạn tận hưởng những giây phút nghỉ ngơi.');
INSERT INTO `room_categories` VALUES (2, 0, 12000000.00, 2, 400000.00, 200000.00, 1, 0, 1, 1, 2, 1, 42, 11, '1 Giường Queen 1m8', 'Hướng vườn thiền', 'https://i.pinimg.com/1200x/43/cd/86/43cd86b688531a000a4aee8be3befb61.jpg,https://i.pinimg.com/736x/0e/84/24/0e8424cfb4d5baffaba3c5d85d9036c9.jpg,https://i.pinimg.com/1200x/ea/c5/81/eac581a1d4dcbe2279e1170452dbcb0a.jpg', 'Traditional Room', '2 chai nước suối, Trà sen truyền thống', 'Không gian nghỉ dưỡng thấm đẫm nét đẹp truyền thống mộc mạc, mang hơi thở văn hóa Á Đông thanh bình, giúp bạn tìm lại sự thư thái tĩnh tại trong tâm hồn.');
