INSERT INTO `tour_itineraries` VALUES (1, 1, 1, 'Hành trình Cố đô', 'Khám phá Đại Nội Huế và lăng tẩm hoàng cung triều Nguyễn.');
INSERT INTO `tour_itineraries` VALUES (1, 2, 2, 'Hồn Quê Xứ Quảng', 'Tham quan Hội An cổ kính và trải nghiệm cày cấy làng Trà Quế.');
INSERT INTO `tour_itineraries` VALUES (1, 3, 3, 'Hồn Đất Văn Lâm', 'Đi thuyền Vân Long ngắm cảnh sơn thuỷ và xem dệt thêu thủ công.');
INSERT INTO `tour_itineraries` VALUES (1, 4, 4, 'Thiền Giữa Hương Sen', 'Ngắm sen nở mờ sương và tập yoga thiền trên sông nước.');
INSERT INTO `tour_itineraries` VALUES (1, 5, 5, 'Vịnh Xanh Kì Vĩ', 'Tàu sang lướt sóng ngắm hang luồn, hòn trống mái.');
INSERT INTO `tour_itineraries` VALUES (1, 6, 6, 'Sapa Mây Mù', 'Thăm bản H’mông cổ xưa, tìm hiểu nghệ thuật nhuộm chàm.');
INSERT INTO `tour_itineraries` VALUES (1, 7, 7, 'Khám Phá Rừng Xanh', 'Đi bộ xuyên rừng ngắm bằng lăng cổ thụ kì vĩ.');
INSERT INTO `tour_itineraries` VALUES (1, 8, 8, 'Cát Vàng Mũi Né', 'Ngắm bình minh cồn cát trắng, tham quan Suối Tiên.');
INSERT INTO `tour_itineraries` VALUES (1, 9, 9, 'Đại Dương Phú Quốc', 'Lặn cano 4 đảo nhỏ hoang sơ hoà vào san hô rực rỡ.');
INSERT INTO `tour_itineraries` VALUES (1, 10, 10, 'Sông Nước Cần Thơ', 'Ăn sáng hủ tiếu chợ nổi Cái Răng sôi động.');
INSERT INTO `tour_itinerary_details` VALUES ('08:00:00', '07:30:00', 1, 1, NULL, NULL, 'Đón khách & Làm thủ tục', 'Đón khách tại sảnh chính Resort, làm thủ tục nhận diện khuôn mặt FaceID và kiểm tra hành lý trước khi khởi hành.');
INSERT INTO `tour_itinerary_details` VALUES ('11:30:00', '08:00:00', 2, 1, NULL, NULL, 'Dấu xưa rêu phong – Khám phá Đại Nội', 'Dạo bước qua những lầu son gác tía, lắng nghe tiếng vọng của thời gian tại Điện Thái Hòa, Thế Miếu – nơi lưu giữ trọn vẹn nét uy nghi một thuở hoàng kim.');
INSERT INTO `tour_itinerary_details` VALUES ('14:00:00', '11:30:00', 3, 1, NULL, NULL, 'Vị đượm cung đình – Thưởng yến và nếm trà', 'Thưởng thức bữa trưa được tái hiện theo phong cách cung đình. Sau đó, ghé thăm Duyệt Thị Đường để nhấp ngụm trà thảo mộc thanh mát, được pha chế theo công thức tiến vua ngày trước.');
INSERT INTO `tour_itinerary_details` VALUES ('18:00:00', '14:00:00', 4, 1, NULL, NULL, 'Sông Hương bảng lảng – Thuyền rồng đón hoàng hôn', 'Ngồi trên mạn thuyền rồng, thong dong ngắm dòng sông Hương êm đềm, thả hồn theo điệu hò xứ Huế và đón ánh chiều tà buông chậm xuống những mái ngói cổ kính.');
INSERT INTO `tour_itinerary_details` VALUES ('18:30:00', '18:00:00', 5, 1, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Đưa đoàn khách quay trở về an toàn tại Resort, hỗ trợ nhận hành lý và chào tạm biệt khách.');
INSERT INTO `tour_itinerary_details` VALUES ('08:30:00', '08:00:00', 6, 2, NULL, NULL, 'Đón khách & Làm thủ tục', 'Chào đón khách, thực hiện điểm danh FaceID và chuẩn bị các vật dụng như nón lá, nước uống giải khát.');
INSERT INTO `tour_itinerary_details` VALUES ('11:00:00', '08:30:00', 7, 2, NULL, NULL, 'Hồn của đất – Làng gốm Thanh Hà', 'Bên dòng sông Thu Bồn lộng gió, bạn sẽ được ngắm nhìn các nghệ nhân thổi hồn vào đất và tự tay xoay vần, nhào nặn nên một món quà kỷ niệm của riêng mình.');
INSERT INTO `tour_itinerary_details` VALUES ('13:00:00', '11:00:00', 8, 2, NULL, NULL, 'Hương đồng cỏ nội – Làng rau Trà Quế', 'Hòa mình vào không gian xanh mướt của một trong những vườn rau lâu đời nhất. Trải nghiệm một ngày làm nông nhẹ nhàng, xới đất gieo mầm và thưởng thức ngụm nước hạt sen thanh mát.');
INSERT INTO `tour_itinerary_details` VALUES ('15:30:00', '13:00:00', 9, 2, NULL, NULL, 'Vị quê đậm đà – Ẩm thực sân vườn', 'Thưởng thức bữa trưa ấm cúng với những món ăn đặc sản xứ Quảng, được chế biến từ chính nguồn nông sản tươi ngon vừa thu hoạch tại vườn.');
INSERT INTO `tour_itinerary_details` VALUES ('18:30:00', '15:30:00', 10, 2, NULL, NULL, 'Hoài phố rêu phong – Tản bộ và thưởng trà chiều', 'Di chuyển về trung tâm Phố cổ Hội An, thong thả dạo bước qua những nếp nhà vàng cổ kính và dừng chân thưởng thức trà thảo mộc ngắm hoàng hôn buông trên dòng sông Hoài.');
INSERT INTO `tour_itinerary_details` VALUES ('19:00:00', '18:30:00', 11, 2, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Xe đưa khách trở về lại Resort, bàn giao hành lý và lắng nghe ý kiến phản hồi nhanh của khách.');
INSERT INTO `tour_itinerary_details` VALUES ('09:00:00', '08:30:00', 12, 3, NULL, NULL, 'Đón khách & Làm thủ tục', 'Tập trung khách tại bến đón, check-in FaceID và nhắc nhở hướng dẫn an toàn cơ bản cho khách.');
INSERT INTO `tour_itinerary_details` VALUES ('11:30:00', '09:00:00', 13, 3, NULL, NULL, 'Sợi cói dệt nắng – Làng chiếu Kim Sơn', 'Ngắm nhìn quy trình dệt nên những chiếc chiếu cói tự nhiên đượm hương đồng nội. Bạn sẽ hiểu vì sao những sợi cỏ mềm mại qua tay người thợ lại trở thành những tác phẩm tinh xảo đến vậy.');
INSERT INTO `tour_itinerary_details` VALUES ('14:00:00', '11:30:00', 14, 3, NULL, NULL, 'Hương vị cố đô – Thưởng thức đặc sản', 'Ghé thăm nhà hàng cao cấp ven sông để thưởng thức bữa trưa đậm đà vị núi rừng với thịt dê truyền thống, cơm cháy giòn rụm và các sản vật địa phương.');
INSERT INTO `tour_itinerary_details` VALUES ('16:30:00', '14:00:00', 15, 3, NULL, NULL, 'Đốm hoa trên gấm – Làng thêu Văn Lâm', 'Thu mình vào không gian yên ắng của làng thêu cổ, lắng nghe những câu chuyện xưa và học cách đưa thoi, điểm nhụy để tự tay dệt nên những nét hoa văn truyền thống tinh tế.');
INSERT INTO `tour_itinerary_details` VALUES ('19:00:00', '16:30:00', 16, 3, NULL, NULL, 'Sơn thủy hữu tình – Thuyền nan lướt bóng hoàng hôn', 'Di chuyển đến đầm bảo tồn Vân Long, ngồi trên chiếc thuyền nan mộc mạc rẽ nước qua những hốc đá, ngắm nhìn đàn voọc quý hiếm và đón chiều tà buông xuống lòng thung lũng tĩnh mịch.');
INSERT INTO `tour_itinerary_details` VALUES ('19:30:00', '19:00:00', 17, 3, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Xe trung chuyển đón khách đưa về an toàn tại khu nghỉ dưỡng.');
INSERT INTO `tour_itinerary_details` VALUES ('08:00:00', '07:30:00', 18, 4, NULL, NULL, 'Đón khách & Làm thủ tục', 'Thực hiện thủ tục FaceID nhanh chóng, nhắc nhở khách chuyển thiết bị di động sang chế độ rung để bắt đầu tour thiền hành.');
INSERT INTO `tour_itinerary_details` VALUES ('11:00:00', '08:00:00', 19, 4, NULL, NULL, 'Đón sương sớm – Thả thuyền ngắm sen', 'Ngồi trên chiếc xuồng ba lá lướt nhẹ giữa đầm sương, ngắm nhìn những đóa sen hồng bung nở trong nắng sớm và hít hà hương thơm tinh khôi của đất trời.');
INSERT INTO `tour_itinerary_details` VALUES ('13:30:00', '11:00:00', 20, 4, NULL, NULL, 'Tâm an giữa đầm – Thiền hành và thưởng trà', 'Thong thả dạo bước trên những cây cầu gỗ nhỏ giữa lòng đầm, rũ bỏ những lo toan. Sau đó, tĩnh lặng thưởng thức ngụm trà sen ủ qua đêm ngọt hậu, thơm dịu.');
INSERT INTO `tour_itinerary_details` VALUES ('16:00:00', '13:30:00', 21, 4, NULL, NULL, 'Hương sen kết tinh – Mỹ tiệc bách hoa', 'Thưởng thức bữa trưa độc đáo với thực đơn sáng tạo trọn vẹn từ sen: từ cơm hấp lá sen dẻo thơm, súp hạt sen bổ dưỡng cho đến đĩa gỏi ngó sen thanh mát, giòn rụm.');
INSERT INTO `tour_itinerary_details` VALUES ('18:00:00', '16:00:00', 22, 4, NULL, NULL, 'Sông nước tịch mịch – Nghỉ ngơi tĩnh tại', 'Thư giãn tự do bên hiên nhà tre lộng gió, ngắm hoàng hôn nhuộm đỏ cánh đồng sen và lắng nghe tiếng chim bay về tổ, khép lại ngày bình yên.');
INSERT INTO `tour_itinerary_details` VALUES ('18:30:00', '18:00:00', 23, 4, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Đưa đoàn khách thiền hành trở về an toàn tại Resort, khép lại ngày bình yên.');
INSERT INTO `tour_itinerary_details` VALUES ('08:00:00', '07:30:00', 24, 5, NULL, NULL, 'Đón khách & Làm thủ tục', 'Hướng dẫn khách lên du thuyền, điểm danh AI FaceID và phát túi chống nước bảo vệ thiết bị cá nhân cho khách.');
INSERT INTO `tour_itinerary_details` VALUES ('09:30:00', '08:00:00', 25, 5, NULL, NULL, 'Hải trình sóng vỗ – Rẽ nước thưởng ngoạn', 'Du thuyền hạng sang khởi hành đưa bạn hòa mình vào không gian bao la của vịnh Hạ Long, ngắm nhìn những đảo đá vôi mang muôn vàn hình dáng kỳ thú.');
INSERT INTO `tour_itinerary_details` VALUES ('12:00:00', '09:30:00', 26, 5, NULL, NULL, 'Tuyệt tác giấu kín – Khám phá động Thiên Cung', 'Dạo bước vào lòng động cùng hướng dẫn viên riêng, chiêm ngưỡng những khối thạch nhũ lấp lánh và lắng nghe những câu chuyện huyền thoại cổ xưa.');
INSERT INTO `tour_itinerary_details` VALUES ('14:30:00', '12:00:00', 27, 5, NULL, NULL, 'Mỹ vị giữa trùng khơi – Thưởng thức tiệc trưa', 'Dùng bữa trưa hải sản cao cấp được chế biến tinh tế bởi đầu bếp trên tàu, trong khi du thuyền chầm chậm lướt qua những vùng vịnh tĩnh lặng, hoang sơ.');
INSERT INTO `tour_itinerary_details` VALUES ('16:30:00', '14:30:00', 28, 5, NULL, NULL, 'Góc nhỏ tĩnh lặng – Chèo thuyền Kayak & Tắm biển', 'Tàu neo lại tại một bãi biển hoang vắng, bạn tự do chèo thuyền kayak len lỏi qua các hang luồn hoặc ngâm mình trong làn nước xanh mát.');
INSERT INTO `tour_itinerary_details` VALUES ('18:00:00', '16:30:00', 29, 5, NULL, NULL, 'Khúc ca lộng gió – Tiệc trà ngắm hoàng hôn', 'Thư giãn trên boong tàu đón gió biển mát lành, thưởng thức tiệc trà chiều, bánh ngọt và ngắm ánh chiều tà vàng rực buông chậm xuống vịnh biển ngàn năm.');
INSERT INTO `tour_itinerary_details` VALUES ('18:30:00', '18:00:00', 30, 5, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Du thuyền cập bến bãi, xe đưa khách quay trở về khu nghỉ dưỡng an toàn.');
INSERT INTO `tour_itinerary_details` VALUES ('08:00:00', '07:30:00', 31, 6, NULL, NULL, 'Đón khách & Làm thủ tục', 'Đón đoàn, quét vân FaceID điểm danh hành trình leo núi dã ngoại.');
INSERT INTO `tour_itinerary_details` VALUES ('11:30:00', '08:00:00', 32, 6, NULL, NULL, 'Nẻo đường mây phủ – Thăm bản Cát Cát', 'Thong thả đi bộ dọc theo những lối mòn dẫn vào bản, ngắm nhìn những chiếc cối xay nước khổng lồ quay đều bên suối và trải nghiệm nghệ thuật nhuộm chàm cùng nghệ nhân bản địa.');
INSERT INTO `tour_itinerary_details` VALUES ('14:00:00', '11:30:00', 33, 6, NULL, NULL, 'Bếp lửa vùng cao – Ẩm thực Tây Bắc', 'Dừng chân nghỉ ngơi tại không gian nhà hàng cao cấp view toàn cảnh thung lũng, thưởng thức bữa trưa ấm cúng với những món ăn đậm đà hương vị núi rừng.');
INSERT INTO `tour_itinerary_details` VALUES ('16:30:00', '14:00:00', 34, 6, NULL, NULL, 'Tiếng hát của dòng suối – Thác Tiên Sa', 'Check-in dòng thác Tiên Sa bọt tung trắng xóa, tản bộ dọc bờ suối và lắng nghe những giai điệu khèn môi mộc mạc của người bản địa.');
INSERT INTO `tour_itinerary_details` VALUES ('19:00:00', '16:30:00', 35, 6, NULL, NULL, 'Tĩnh lặng đại ngàn – Thưởng trà chiều ngắm hoàng hôn', 'Di chuyển về một quán trà bản địa không gian mở trên đỉnh đồi, thưởng thức ngụm trà cổ thụ, ngắm nhìn thung lũng Mường Hoa chìm dần vào sương mờ hoàng hôn.');
INSERT INTO `tour_itinerary_details` VALUES ('19:30:00', '19:00:00', 36, 6, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Đưa hành khách quay trở lại điểm tập kết của Resort, kết thúc ngày trekking.');
INSERT INTO `tour_itinerary_details` VALUES ('08:00:00', '07:30:00', 37, 7, NULL, NULL, 'Đón khách & Làm thủ tục', 'Điểm danh FaceID hành khách, phát thuốc chống vắt và kem xịt côn trùng chuyên dụng cho khách.');
INSERT INTO `tour_itinerary_details` VALUES ('12:00:00', '08:00:00', 38, 7, NULL, NULL, 'Dưới bóng đại ngàn – Trekking Bàu Sấu', 'Lội bộ dưới những tán cây cổ thụ trăm tuổi, hít hà bầu không khí trong lành của rừng nguyên sinh để đến với vùng đầm lầy Bàu Sấu hoang sơ.');
INSERT INTO `tour_itinerary_details` VALUES ('14:30:00', '12:00:00', 39, 7, NULL, NULL, 'Bên bờ đầm vắng – Trưa xanh tĩnh lặng', 'Thưởng thức bữa trưa tinh tế được chuẩn bị riêng bên trạm kiểm lâm, ngắm nhìn những chú chim quý hiếm và cá sấu tự nhiên bơi lội dưới làn nước.');
INSERT INTO `tour_itinerary_details` VALUES ('18:00:00', '14:30:00', 40, 7, NULL, NULL, 'Khúc giao mùa rừng già – Tản bộ lượt về', 'Quay trở lại trung tâm bằng đường rừng, đón ánh nắng chiều xuyên qua những kẽ lá và nghỉ ngơi, ngâm chân thảo mộc thư giãn tại resort bìa rừng.');
INSERT INTO `tour_itinerary_details` VALUES ('20:00:00', '18:00:00', 41, 7, NULL, NULL, 'Hương vị đại ngàn – Bữa tối lãng mạn', 'Thưởng thức bữa tối ấm cúng tại nhà hàng ven sông của resort với các món ăn mang phong vị địa phương, lắng nghe tiếng côn trùng reo vang.');
INSERT INTO `tour_itinerary_details` VALUES ('22:00:00', '20:00:00', 42, 7, NULL, NULL, 'Thanh âm bóng tối – Đi xe mui trần xem thú đêm', 'Lên xe chuyên dụng mui trần len lỏi vào bìa rừng, dưới ánh đèn chuyên dụng, bạn sẽ được tận mắt ngắm nhìn cuộc sống kiếm ăn ban đêm đầy thú vị của các loài thú hoang dã.');
INSERT INTO `tour_itinerary_details` VALUES ('22:30:00', '22:00:00', 43, 7, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Xe trung chuyển đưa đoàn về phòng an toàn nghỉ ngơi.');
INSERT INTO `tour_itinerary_details` VALUES ('04:30:00', '04:00:00', 44, 8, NULL, NULL, 'Đón khách & Làm thủ tục', 'Khởi hành sớm, điểm danh FaceID khách lên xe sang trọng.');
INSERT INTO `tour_itinerary_details` VALUES ('05:30:00', '04:30:00', 45, 8, NULL, NULL, 'Đường chạy ban mai – Hành trình ra đồi cát', 'Xe hạng sang đón bạn từ sớm khi trời còn đẫm sương để kịp di chuyển ra Đồi Cát Trắng xinh đẹp.');
INSERT INTO `tour_itinerary_details` VALUES ('07:30:00', '05:30:00', 46, 8, NULL, NULL, 'Nắng ấm sa mạc – Xe địa hình & Đón bình minh', 'Riêng tư trải nghiệm xe địa hình ATV lao vút qua những đụn cát nhấp nhô, ngắm mặt trời nhô lên từ phía biển và chơi trượt cát bằng máng từ đỉnh đồi.');
INSERT INTO `tour_itinerary_details` VALUES ('09:30:00', '07:30:00', 47, 8, NULL, NULL, 'Bức họa của gió – Đồi Cát Đỏ & Suối Tiên', 'Tiếp tục check-in Đồi Cát Đỏ lộng gió và dạo bước chân trần dưới làn nước mát rượi của dòng Suối Tiên, ngắm nhìn những bức vách đất sét màu cam rực rỡ.');
INSERT INTO `tour_itinerary_details` VALUES ('12:30:00', '09:30:00', 48, 8, NULL, NULL, 'Sóng vỗ rì rào – Thư giãn tại Beach Club', 'Di chuyển về một resort sát biển cao cấp, tự do tắm hồ bơi, tắm biển hoặc nằm nghỉ ngơi dưới bóng mát, thưởng thức ly nước dừa mát lạnh.');
INSERT INTO `tour_itinerary_details` VALUES ('15:30:00', '12:30:00', 49, 8, NULL, NULL, 'Vị mặn biển khơi – Bữa trưa hải sản thượng hạng', 'Thưởng thức bữa trưa với thực đơn hải sản tươi sống được đánh bắt trong ngày tại nhà hàng view biển sang trọng trước khi xe đưa bạn về lại điểm đón ban đầu.');
INSERT INTO `tour_itinerary_details` VALUES ('16:00:00', '15:30:00', 50, 8, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Xe đưa khách về lại điểm Resort ban đầu an toàn.');
INSERT INTO `tour_itinerary_details` VALUES ('08:30:00', '08:00:00', 51, 9, NULL, NULL, 'Đón khách & Làm thủ tục', 'Check-in FaceID hành khách tại cầu cảng, phát áo phao an toàn cho từng khách.');
INSERT INTO `tour_itinerary_details` VALUES ('10:30:00', '08:30:00', 52, 9, NULL, NULL, 'Lướt sóng trùng khơi – Khám phá các hòn đảo hoang', 'Cano tốc độ cao thế mới đưa bạn rời bến cảng, băng qua làn nước xanh ngắt để ghé thăm những hòn đảo nhỏ còn giữ nguyên nét hoang sơ.');
INSERT INTO `tour_itinerary_details` VALUES ('13:00:00', '10:30:00', 53, 9, NULL, NULL, 'Vũ điệu đại dương – Bơi lặn ngắm san hô', 'Đeo ống thở và kính lặn chuyên dụng, thỏa thích hòa mình vào làn nước trong vắt để ngắm nhìn những rạn san hô đung đưa cùng từng đàn cá nhỏ rực rỡ sắc màu.');
INSERT INTO `tour_itinerary_details` VALUES ('15:30:00', '13:00:00', 54, 9, NULL, NULL, 'Vị mặn của biển – Bữa trưa trên đảo hoang', 'Thưởng thức bữa trưa hải sản cao cấp tươi ngon ngay trên bãi biển cát trắng mịn, ngả lưng dưới bóng dừa mát rượi.');
INSERT INTO `tour_itinerary_details` VALUES ('18:30:00', '15:30:00', 55, 9, NULL, NULL, 'Đảo ngọc hoàng hôn – Tiệc cocktail chiều tà', 'Cano đưa bạn đến một hòn đảo ngắm hoàng hôn đẹp nhất. Tại đây, bạn có thể thong thả đi dạo, thưởng thức ly cocktail mát lạnh và đón khoảnh khắc mặt trời lặn nhuộm hồng cả đường chân trời trước khi trở về bến cảng lúc 18:30.');
INSERT INTO `tour_itinerary_details` VALUES ('19:00:00', '18:30:00', 56, 9, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Bàn giao và trả khách tại điểm đón của khu nghỉ dưỡng.');
INSERT INTO `tour_itinerary_details` VALUES ('05:30:00', '05:00:00', 57, 10, NULL, NULL, 'Đón khách & Làm thủ tục', 'Chào đón đoàn khách lúc bình minh, check-in FaceID và hỗ trợ khách bước xuống ghe máy an toàn.');
INSERT INTO `tour_itinerary_details` VALUES ('06:00:00', '05:30:00', 58, 10, NULL, NULL, 'Sương sớm trên sông – Xuống bến xuống tàu', 'Đón ngày mới khi trời còn mờ sương, xuống chiếc ghe máy truyền thống được chuẩn bị riêng để bắt đầu chuyến hành trình dọc theo dòng sông Hậu.');
INSERT INTO `tour_itinerary_details` VALUES ('08:30:00', '06:00:00', 59, 10, NULL, NULL, 'Âm thanh ngày mới – Chợ nổi Cái Răng', 'Len lỏi qua những chiếc ghe đơm đầy hoa trái, lắng nghe tiếng rao của người dân miền Tây và thưởng thức bữa sáng với tô hủ tiếu nóng hổi, chòng chành ngay trên mặt nước từ ghe hậu cần riêng của tour.');
INSERT INTO `tour_itinerary_details` VALUES ('11:30:00', '08:30:00', 60, 10, NULL, NULL, 'Trái ngọt trĩu cành – Thăm vườn cây ăn trái', 'Ghé thăm một miệt vườn cây ăn trái sum suê, thong thả dạo bước dưới bóng mát, tự tay hái và thưởng thức quả chín mọng ngọt lịm ngay tại vườn.');
INSERT INTO `tour_itinerary_details` VALUES ('13:30:00', '11:30:00', 61, 10, NULL, NULL, 'Trải nghiệm làm bánh dân gian', 'Đến với gian nhà cổ Nam Bộ, cùng các nghệ nhân miệt vườn học cách đổ bánh xèo, làm bánh tằm se tay và lắng nghe những câu chuyện đời sống mộc mạc.');
INSERT INTO `tour_itinerary_details` VALUES ('15:30:00', '13:30:00', 62, 10, NULL, NULL, 'Phong vị sông nước – Bữa trưa điền dã', 'Thưởng thức bữa trưa đậm chất miền Tây với cá lóc nướng trui, lẩu mắm đậm đà tại nhà hàng lộng gió ven sông, nghỉ ngơi tĩnh tại trên những chiếc võng trước khi kết thúc hành trình.');
INSERT INTO `tour_itinerary_details` VALUES ('16:00:00', '15:30:00', 63, 10, NULL, NULL, 'Trả khách & Kết thúc hành trình', 'Ghe cập bến tàu, xe đưa khách quay trở về Resort an toàn.');
INSERT INTO `tour_locations` VALUES (1, 16.46780000, 107.57890000, 1, 'Đại Nội Huế', 'Hoàng cung triều Nguyễn cổ kính, uy nghiêm.');
INSERT INTO `tour_locations` VALUES (1, 15.88010000, 108.33800000, 2, 'Phố cổ Hội An', 'Di sản văn hoá thế giới thương cảng đèn lồng rực rỡ.');
INSERT INTO `tour_locations` VALUES (1, 20.36210000, 105.90870000, 3, 'Đầm Vân Long', 'Khu bảo tồn thiên nhiên ngập nước lớn nhất vịnh Bắc Bộ.');
INSERT INTO `tour_locations` VALUES (1, 10.45000000, 105.70000000, 4, 'Đồng Tháp Mười', 'Xứ sở sen hồng ngào ngạt ngút ngàn tầm mắt.');
INSERT INTO `tour_locations` VALUES (1, 20.86540000, 107.08120000, 5, 'Đảo Ti Tốp Hạ Long', 'Bãi tắm cát trắng tuyệt đẹp tựa lưng vách đá.');
INSERT INTO `tour_locations` VALUES (1, 22.32890000, 103.84150000, 6, 'Bản Cát Cát Sapa', 'Bản làng mộc mạc bên thác nước mát rượi.');
INSERT INTO `tour_locations` VALUES (1, 11.45890000, 107.36540000, 7, 'Bàu Sấu Cát Tiên', 'Vùng đầm lầy bảo tồn cá sấu tự nhiên quý hiếm.');
INSERT INTO `tour_locations` VALUES (1, 10.95000000, 108.28000000, 8, 'Đồi Cát Trắng Mũi Né', 'Tiểu sa mạc cát mênh mông lấp lánh ánh vàng.');
INSERT INTO `tour_locations` VALUES (1, 9.95430000, 104.01520000, 9, 'Hòn Thơm Phú Quốc', 'Thiên đường đảo ngọc cát trắng nước trong vắt.');
INSERT INTO `tour_locations` VALUES (1, 9.99890000, 105.74890000, 10, 'Chợ nổi Cái Răng', 'Chợ đầu mối mua bán trái cây sầm uất trên sông.');
